import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadAshtamudiLakeData(){const e=readFileSync(resolve(__dirname,"../../frontend/ashtamudi-lake-explorer/ashtamudi-lake-data.js"),"utf-8");return new Function(e+"\nreturn { ASHTAMUDI_LAKE_INFO, ECOLOGY_HYDROLOGY, WILDLIFE_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Ashtamudi Lake Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadAshtamudiLakeData()}),describe("ASHTAMUDI_LAKE_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.ASHTAMUDI_LAKE_INFO.id).toBe("ashtamudi-lake-explorer"),expect(e.ASHTAMUDI_LAKE_INFO.name).toContain("Ashtamudi"),expect(e.ASHTAMUDI_LAKE_INFO.ramsarYear).toBe(2002),expect(e.ASHTAMUDI_LAKE_INFO.ramsarSiteNo).toBe(1214),expect(e.ASHTAMUDI_LAKE_INFO.state).toBe("Kerala")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.ASHTAMUDI_LAKE_INFO.quickStats)).toBe(!0),expect(e.ASHTAMUDI_LAKE_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains ramsarSite, backwaters, houseboats, mangroves, fisheries, and birdlife",()=>{expect(e.ECOLOGY_HYDROLOGY.ramsarSite).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.backwaters).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.houseboats).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.mangroves).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.fisheries).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.birdlife).toBeDefined()})}),describe("WILDLIFE_SPECIES catalog",()=>{it("is a non-empty array of species",()=>{expect(Array.isArray(e.WILDLIFE_SPECIES)).toBe(!0),expect(e.WILDLIFE_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Stork-billed Kingfisher",()=>{const t=e.WILDLIFE_SPECIES.find(e=>"stork-billed-kingfisher"===e.id);expect(t).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"ashtamudi-lake"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../ashtamudi-lake-explorer/index.html")})})});